INSERT INTO "public"."brain_map_collocations" VALUES ('5854f2b2-2de5-43ed-b090-50e76270a187', 'dc795048-cd34-449f-a347-865895415516', 'maintain a relationship', '관계를 유지하다', 'They maintained a close relationship for twenty years.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('4e84780e-c8d6-4153-a05a-68a1eedbe376', 'dc795048-cd34-449f-a347-865895415516', 'maintain quality', '품질을 유지하다', 'Small farms find it hard to maintain quality at scale.', 1, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('d9521103-dbc7-48e1-a3c0-bfa3f1699f6c', 'dc795048-cd34-449f-a347-865895415516', 'maintain order', '질서를 유지하다', 'The teachers struggled to maintain order in the hall.', 2, 2);
INSERT INTO "public"."brain_map_collocations" VALUES ('004d8b6a-3ce0-41c5-a0c1-d31d4b6c6e9f', 'dc795048-cd34-449f-a347-865895415516', 'maintain control', '통제력을 유지하다', 'She maintained control of the car on the icy road.', 2, 3);
INSERT INTO "public"."brain_map_collocations" VALUES ('3b9ef1b0-65a3-4b95-a809-2641c3cb0847', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'directly affect', '직접적으로 영향을 미치다', 'The new rule directly affects part-time workers.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('180c7ab9-c44a-43f9-9f9c-ceb06bc5b205', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'adversely affect', '악영향을 미치다', 'Lack of sleep adversely affects concentration.', 2, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('005496f8-a81c-4f11-9a57-23c940957b8a', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'be deeply affected by', '~에 깊이 영향을 받다', 'The whole town was deeply affected by the flood.', 2, 2);
INSERT INTO "public"."brain_map_collocations" VALUES ('bacb03c1-8ef9-4159-82f6-dffb5d52f524', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'raise an issue', '문제를 제기하다', 'She raised the issue at the staff meeting.', 1, 0);
INSERT INTO "public"."brain_map_collocations" VALUES ('54b60029-0277-429d-8b8f-057a5bc59357', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'address an issue', '문제를 다루다', 'The report fails to address the real issue.', 1, 1);
INSERT INTO "public"."brain_map_collocations" VALUES ('d42a8a67-ef06-45bb-a40e-a09a630528a6', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'a controversial issue', '논란이 되는 쟁점', 'Voting age is a controversial issue in many countries.', 2, 2);

--
