--

INSERT INTO "public"."brain_map_meanings" VALUES ('2dab8ba8-fdad-48da-acdc-6977e5fc14e1', 'dc795048-cd34-449f-a347-865895415516', '(상태를) 유지하다', 'to keep something at the same level or in the same condition', '핵심 의미가 가장 직접적으로 드러나는 용법. 가만히 두는 것이 아니라 노력해서 계속 이어가는 것이 포인트다.', 'maintain good health', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('8a2e3269-d62a-46fc-ae9f-5f5d8a43317e', 'dc795048-cd34-449f-a347-865895415516', '(기계·건물을) 정비하다, 관리하다', 'to keep equipment in good condition by checking and repairing it', '상태를 계속 이어지게 하려면 손봐야 한다. "유지하다"에 실제 작업이 붙은 용법.', 'maintain a machine', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('0be134b3-edaa-4a52-9ec5-444c31607473', 'dc795048-cd34-449f-a347-865895415516', '(의견을) 계속 주장하다', 'to keep saying that something is true, even when others disagree', '유지되는 대상이 상태가 아니라 "내 입장"인 경우. 반대에도 입장을 끊지 않고 이어간다는 점에서 핵심 의미와 연결된다.', 'maintain his innocence', 2);
INSERT INTO "public"."brain_map_meanings" VALUES ('5ffa683f-f289-492d-88a8-c74e7d3ab542', '5c44d86e-d63b-4570-ac1a-523628e455cc', '~에 영향을 미치다', 'to cause a change in something', '가장 기본적인 용법. 목적어를 바로 취하는 타동사라서 "affect to"처럼 쓰지 않는다.', 'affect the results', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('7a7d0e2e-b23e-44a4-9bf0-485d502f816e', '5c44d86e-d63b-4570-ac1a-523628e455cc', '(감정적으로) 마음을 움직이다', 'to cause a strong emotion in someone', '"바꾸다"의 대상이 사람의 마음인 경우. 보통 수동태 be deeply affected 형태로 자주 쓰인다.', 'deeply affected by the news', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('5ded513a-ebdd-49ae-99b5-0248842aa972', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', '(다뤄야 할) 문제, 쟁점', 'an important topic that people are discussing or arguing about', '드러나서 다 같이 다뤄야 하는 상태가 된 것. problem과 달리 "해결해야 할 골칫거리"보다 "논의 대상"에 가깝다.', 'an important issue', 0);
INSERT INTO "public"."brain_map_meanings" VALUES ('9fcb98fb-444c-452d-9ece-931e56fcbf3f', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', '(정기 간행물의) 호', 'one of a regular series of a magazine or newspaper', '"밖으로 내보낸 것"이라는 감각. 이번 달에 세상에 나온 한 권이 this month’s issue다.', 'this month''s issue', 1);
INSERT INTO "public"."brain_map_meanings" VALUES ('3c93158b-1195-41a1-a07d-454d178e92c0', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', '(공식적으로) 발급하다, 발표하다', 'to officially give out or announce something', '동사로 쓰일 때의 용법. 기관이 무언가를 밖으로 내보낸다는 점에서 명사 뜻과 뿌리가 같다.', 'issue a statement', 2);

