INSERT INTO "public"."brain_map_sentences" VALUES ('a77e781f-f8fa-4bf6-91f7-04826fa142df', 'dc795048-cd34-449f-a347-865895415516', 'Regular exercise helps maintain good health.', '규칙적인 운동은 건강을 유지하는 데 도움이 된다.', '상태를 유지하다', 'maintain good health', 1, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('11c6bea6-2871-42e1-99d6-c98eaaaa4af0', 'dc795048-cd34-449f-a347-865895415516', 'It is difficult to maintain a long-distance relationship.', '장거리 연애를 유지하는 것은 어렵다.', '관계를 이어가다', 'maintain a long-distance relationship', 2, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('7f6705e4-3de4-4e57-81c1-741e2a4154fe', 'dc795048-cd34-449f-a347-865895415516', 'The machine must be properly maintained to work safely.', '그 기계는 안전하게 작동하려면 제대로 정비되어야 한다.', '기계를 정비하다', 'properly maintained', 3, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('d66a662f-e5e2-4275-b88b-687b4d0fcb75', 'dc795048-cd34-449f-a347-865895415516', 'He maintained that he had never seen the document.', '그는 그 문서를 결코 본 적이 없다고 주장했다.', '의견을 주장하다', 'maintained that', 4, 3);
INSERT INTO "public"."brain_map_sentences" VALUES ('ddbafe9e-7f3f-418a-8598-488792355ced', 'dc795048-cd34-449f-a347-865895415516', 'The company struggled to maintain quality as it grew.', '그 회사는 성장하면서 품질을 유지하는 데 어려움을 겪었다.', '수준을 유지하다', 'maintain quality', 3, 4);
INSERT INTO "public"."brain_map_sentences" VALUES ('fcb1c8d2-2ba9-4cbc-bce0-31efbc3f9d2a', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'The weather can affect how well you sleep.', '날씨는 당신이 얼마나 잘 자는지에 영향을 줄 수 있다.', '영향을 미치다', 'affect how well you sleep', 1, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('2e526680-1548-4a71-87ac-c749ec7101a5', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'Rising prices affect low-income families the most.', '물가 상승은 저소득 가정에 가장 큰 영향을 미친다.', '집단에 영향을 미치다', 'affect low-income families', 2, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('f3138855-d2d4-404b-bb96-9a233694a05c', '5c44d86e-d63b-4570-ac1a-523628e455cc', 'She was deeply affected by her grandfather’s death.', '그녀는 할아버지의 죽음에 깊이 마음이 흔들렸다.', '감정을 움직이다', 'deeply affected', 3, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('08b7b5a4-952d-4eef-8a27-3065a672dfb0', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'Climate change is the most urgent issue of our time.', '기후 변화는 우리 시대의 가장 시급한 문제다.', '사회적 쟁점', 'the most urgent issue', 2, 0);
INSERT INTO "public"."brain_map_sentences" VALUES ('632fdaed-03f9-4d9f-bdee-d81dcfe79878', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'I have an issue with the way this was decided.', '나는 이것이 결정된 방식에 이견이 있다.', '개인적인 이견·불만', 'an issue with', 3, 1);
INSERT INTO "public"."brain_map_sentences" VALUES ('0126b191-220b-489d-9b47-6224bb458d21', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'Her article appeared in last month’s issue.', '그녀의 기사는 지난달 호에 실렸다.', '간행물의 호', 'last month’s issue', 2, 2);
INSERT INTO "public"."brain_map_sentences" VALUES ('1583a5c3-7616-4919-ab69-f39b833aa668', '04a32e48-1f92-4d16-b406-bdfd983d6e5e', 'The government issued a warning about the storm.', '정부는 폭풍에 대한 경보를 발령했다.', '공식적으로 발표하다', 'issued a warning', 3, 3);

