--
-- Data for Name: word_pair_questions; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO "public"."word_pair_questions" VALUES ('c7e09acd-7713-41ac-9451-9924d761174c', '3f02679e-9ef8-4f1b-bd49-e2cee544b7fa', 'The hospital must ___ strict hygiene standards at all times.', 'maintain', '병원이 위생 "기준"을 관리하고 지켜내는 상황이라 maintain이 자연스럽다.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('dc42b683-e209-4b98-b278-8f2e1b20aa58', '3f02679e-9ef8-4f1b-bd49-e2cee544b7fa', 'Please ___ the door open for a second.', 'keep', '잠깐 문을 그 상태로 두라는 일상적인 요청이므로 keep. 여기서 maintain은 지나치게 격식적이다.', 1);
INSERT INTO "public"."word_pair_questions" VALUES ('f4bce2a2-5a54-4ac9-905e-4300f16c3e23', '3f02679e-9ef8-4f1b-bd49-e2cee544b7fa', 'Engineers ___ the bridge twice a year.', 'maintain', '정기적인 점검·보수를 뜻하므로 maintain.', 2);
INSERT INTO "public"."word_pair_questions" VALUES ('717928fd-dbc1-4556-b5dc-e5ff658b9ffb', '750c0488-fc3b-45f4-8b82-54934aa97dfd', 'Too much caffeine can ___ your sleep.', 'affect', 'can 뒤에는 동사가 와야 하므로 affect.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('98b7db32-dd8f-4e77-bcee-01648df52c34', '750c0488-fc3b-45f4-8b82-54934aa97dfd', 'The medicine had no ___ on the pain.', 'effect', 'no 뒤에 오는 명사 자리이므로 effect.', 1);
INSERT INTO "public"."word_pair_questions" VALUES ('dca1ae4b-fd17-4b2a-845f-87c89d71d628', '750c0488-fc3b-45f4-8b82-54934aa97dfd', 'Scientists studied the ___ of sunlight on plants.', 'effect', 'the ___ of 구조는 명사 자리이므로 effect.', 2);
INSERT INTO "public"."word_pair_questions" VALUES ('dff2f942-cab0-4ebb-99ac-42b4ba2316c0', '13be89cc-7392-468b-abcd-92dcb993ef53', 'Privacy is a major ___ in the age of social media.', 'issue', '사회적으로 논의되는 사안이므로 issue.', 0);
INSERT INTO "public"."word_pair_questions" VALUES ('53ff6824-cbe8-4c6f-8df3-7130177a9742', '13be89cc-7392-468b-abcd-92dcb993ef53', 'My laptop has a serious ___ with overheating.', 'problem', '고장이라는 부정적 상황이므로 problem이 자연스럽다.', 1);

--
-- Data for Name: word_pairs; Type: TABLE DATA; Schema: public; Owner: -
--

INSERT INTO "public"."word_pairs" VALUES ('3f02679e-9ef8-4f1b-bd49-e2cee544b7fa', 'keep', 'maintain', 'keep은 그냥 계속 가지고 있거나 그 상태로 두는 것이고, maintain은 그 상태가 무너지지 않도록 의식적으로 노력하는 것이다. 그래서 maintain은 격식 있는 글이나 품질·질서·기계처럼 관리가 필요한 대상에 쓰인다.', '일상적인 "계속 ~하다"는 keep, 노력과 관리가 들어간 "유지하다"는 maintain.', 'approved', 1, NULL, NULL, '2026-09-02 06:43:38.131+00', '2026-09-02 06:43:38.028691+00');
INSERT INTO "public"."word_pairs" VALUES ('750c0488-fc3b-45f4-8b82-54934aa97dfd', 'affect', 'effect', 'affect는 거의 항상 동사로 "영향을 미치다", effect는 거의 항상 명사로 "영향, 결과"다. 발음이 비슷해서 헷갈리지만 문장에서의 자리가 완전히 다르다.', '앞에 the/an이 오면 effect(명사), 주어 뒤에 바로 오면 affect(동사)라고 생각하면 대부분 맞는다.', 'approved', 1, NULL, NULL, '2026-09-02 06:43:38.131+00', '2026-09-02 06:43:38.062269+00');
INSERT INTO "public"."word_pairs" VALUES ('13be89cc-7392-468b-abcd-92dcb993ef53', 'issue', 'problem', 'problem은 반드시 해결해야 하는 나쁜 상황이고, issue는 사람들이 논의하고 있는 사안이다. issue는 중립적일 수 있지만 problem은 거의 항상 부정적이다.', '고쳐야 할 고장·곤란은 problem, 토론하거나 다뤄야 할 사안은 issue.', 'approved', 1, NULL, NULL, '2026-09-02 06:43:38.131+00', '2026-09-02 06:43:38.086503+00');

